          "answerText": "Державу визначають власна територія та верховна незалежна влада, спеціальні органи управління і примусу, правове регулювання та збирання податків. Населення належить до неї за територіальним принципом. Військо, символи, державна мова й власні гроші також характерні для держав, але текст окремо вказує, що деякі з них має більшість, а не неодмінно кожна держава.",
