          "correctKey": "А",
          "answerText": "Корпоративні приписи визначають життя організації та поведінку її членів. Натомість право є системою чітких загальнообов’язкових державних правил. Для порівняння: мораль підтримується громадською оцінкою, релігія — вірою та конфесійними заходами, а звичаї й традиції — тривалою суспільною практикою.",
          "optionSource": "prepared-v21-test",
